window.CHINESE_BANK=[{"hanzi":"一","pinyin":"yī","tones":"1","en":"one","pos":"number","radical":"一","strokes":1,"ex_zh":"我有一本书。","ex_en":"I have one book.","tier":1,"family":"numbers","trap":"First tone is high and flat; do not let it sag."},{"hanzi":"二","pinyin":"èr","tones":"4","en":"two","pos":"number","radical":"二","strokes":2,"ex_zh":"第二课很难。","ex_en":"The second lesson is hard.","tier":1,"family":"numbers","trap":"Fourth tone falls sharply and the tongue curls back; it is not English 'are'."},{"hanzi":"三","pinyin":"sān","tones":"1","en":"three","pos":"number","radical":"一","strokes":3,"ex_zh":"三个人来了。","ex_en":"Three people came.","tier":1,"family":"numbers","trap":"Keep the first tone level; do not confuse it with 山 shān, mountain."},{"hanzi":"四","pinyin":"sì","tones":"4","en":"four","pos":"number","radical":"囗","strokes":5,"ex_zh":"我有四本书。","ex_en":"I have four books.","tier":1,"family":"numbers","trap":"四 sì is four; 十 shí is ten, and the tone is what tells them apart."},{"hanzi":"五","pinyin":"wǔ","tones":"3","en":"five","pos":"number","radical":"二","strokes":4,"ex_zh":"五分钟到了。","ex_en":"Five minutes are up.","tier":1,"family":"numbers","trap":"The third tone dips before rising; before a measure word it is often said low and flat."},{"hanzi":"六","pinyin":"liù","tones":"4","en":"six","pos":"number","radical":"八","strokes":4,"ex_zh":"六月很热。","ex_en":"June is hot.","tier":1,"family":"numbers","trap":"The i is tight and the tone falls; do not say 'loo'."},{"hanzi":"七","pinyin":"qī","tones":"1","en":"seven","pos":"number","radical":"一","strokes":2,"ex_zh":"七天过去了。","ex_en":"Seven days passed.","tier":1,"family":"numbers","trap":"High and flat first tone, unlike the falling 去 qù."},{"hanzi":"八","pinyin":"bā","tones":"1","en":"eight","pos":"number","radical":"八","strokes":2,"ex_zh":"八点上课。","ex_en":"Class starts at eight.","tier":1,"family":"numbers","trap":"The final is an open 'a'; do not add an English r."},{"hanzi":"九","pinyin":"jiǔ","tones":"3","en":"nine","pos":"number","radical":"乙","strokes":2,"ex_zh":"九只小鸟飞。","ex_en":"Nine little birds fly.","tier":1,"family":"numbers","trap":"Dip first, then rise; it is not a flat 'jee-oh'."},{"hanzi":"十","pinyin":"shí","tones":"2","en":"ten","pos":"number","radical":"十","strokes":2,"ex_zh":"十全十美。","ex_en":"Perfect in every way.","tier":1,"family":"numbers","trap":"Second tone rises; do not confuse it with 四 sì, four."},{"hanzi":"百","pinyin":"bǎi","tones":"3","en":"hundred","pos":"number","radical":"白","strokes":6,"ex_zh":"一百块太贵。","ex_en":"A hundred yuan is too expensive.","tier":1,"family":"numbers","trap":"Third tone; b is unaspirated, closer to 'bye' than 'pie'."},{"hanzi":"千","pinyin":"qiān","tones":"1","en":"thousand","pos":"number","radical":"十","strokes":3,"ex_zh":"一千人来了。","ex_en":"A thousand people came.","tier":1,"family":"numbers","trap":"First tone; q is aspirated, unlike j."},{"hanzi":"零","pinyin":"líng","tones":"2","en":"zero","pos":"number","radical":"雨","strokes":13,"ex_zh":"零下五度。","ex_en":"Five degrees below zero.","tier":1,"family":"numbers","trap":"Second tone; keep the final g, which English speakers tend to drop."},{"hanzi":"半","pinyin":"bàn","tones":"4","en":"half","pos":"number","radical":"十","strokes":5,"ex_zh":"半个苹果。","ex_en":"Half an apple.","tier":1,"family":"numbers","trap":"Fourth tone; 半 alone means half, not 'half past' the hour."},{"hanzi":"我","pinyin":"wǒ","tones":"3","en":"I, me","pos":"noun","radical":"戈","strokes":7,"ex_zh":"我是学生。","ex_en":"I am a student.","tier":1,"family":"pronouns","trap":"Third tone dips; in 我们 it is often said low and flat before the neutral syllable."},{"hanzi":"你","pinyin":"nǐ","tones":"3","en":"you (singular)","pos":"noun","radical":"亻","strokes":7,"ex_zh":"你叫什么？","ex_en":"What is your name?","tier":1,"family":"pronouns","trap":"Third tone; n before i is palatal, not like English 'knee'."},{"hanzi":"他","pinyin":"tā","tones":"1","en":"he, him","pos":"noun","radical":"亻","strokes":5,"ex_zh":"他是老师。","ex_en":"He is a teacher.","tier":1,"family":"pronouns","trap":"Same sound as 她; the character, not the tone, marks gender."},{"hanzi":"她","pinyin":"tā","tones":"1","en":"she, her","pos":"noun","radical":"女","strokes":6,"ex_zh":"她是我姐姐。","ex_en":"She is my older sister.","tier":1,"family":"pronouns","trap":"Same sound as 他; the 女 radical marks female, with no change in tone."},{"hanzi":"它","pinyin":"tā","tones":"1","en":"it","pos":"noun","radical":"宀","strokes":5,"ex_zh":"它是一只猫。","ex_en":"It is a cat.","tier":1,"family":"pronouns","trap":"Use 它 for animals and things, never for people."},{"hanzi":"我们","pinyin":"wǒmen","tones":"3 5","en":"we, us","pos":"noun","radical":"戈","strokes":7,"ex_zh":"我们走吧。","ex_en":"Let us go.","tier":1,"family":"pronouns","trap":"The second syllable is neutral: say 'men' lightly, not 'mén'."},{"hanzi":"你们","pinyin":"nǐmen","tones":"3 5","en":"you (plural)","pos":"noun","radical":"亻","strokes":7,"ex_zh":"你们好吗？","ex_en":"How are you all?","tier":1,"family":"pronouns","trap":"Second syllable neutral; 你们 is plural, 你 alone is singular."},{"hanzi":"他们","pinyin":"tāmen","tones":"1 5","en":"they, them (male or mixed)","pos":"noun","radical":"亻","strokes":5,"ex_zh":"他们在家。","ex_en":"They are at home.","tier":1,"family":"pronouns","trap":"Second syllable neutral; 他们 can be a mixed group, 她们 only women."},{"hanzi":"她们","pinyin":"tāmen","tones":"1 5","en":"they, them (female)","pos":"noun","radical":"女","strokes":6,"ex_zh":"她们是同学。","ex_en":"They are classmates.","tier":1,"family":"pronouns","trap":"Second syllable neutral; use 她们 only when every person is female."},{"hanzi":"这","pinyin":"zhè","tones":"4","en":"this","pos":"noun","radical":"辶","strokes":7,"ex_zh":"这是我的书。","ex_en":"This is my book.","tier":1,"family":"pronouns","trap":"Fourth tone; 这 is 'this' and 那 is 'that' — do not swap the vowels."},{"hanzi":"那","pinyin":"nà","tones":"4","en":"that","pos":"noun","radical":"阝","strokes":6,"ex_zh":"那是谁？","ex_en":"Who is that?","tier":1,"family":"pronouns","trap":"Fourth tone with a normal n; some dialects turn it into an l."},{"hanzi":"谁","pinyin":"shéi","tones":"2","en":"who","pos":"noun","radical":"讠","strokes":10,"ex_zh":"他是谁？","ex_en":"Who is he?","tier":1,"family":"pronouns","trap":"Said shéi in speech; the dictionary reading shuí is rare."},{"hanzi":"什么","pinyin":"shénme","tones":"2 5","en":"what","pos":"noun","radical":"亻","strokes":4,"ex_zh":"你在想什么？","ex_en":"What are you thinking about?","tier":1,"family":"pronouns","trap":"The second syllable is neutral: shénme, not shén mó."},{"hanzi":"哪","pinyin":"nǎ","tones":"3","en":"which","pos":"noun","radical":"口","strokes":9,"ex_zh":"你去哪里？","ex_en":"Where are you going?","tier":1,"family":"pronouns","trap":"Third tone; 哪 asks 'which', while 那 nà points to 'that'."},{"hanzi":"爸爸","pinyin":"bàba","tones":"4 5","en":"dad, father","pos":"noun","radical":"父","strokes":8,"ex_zh":"爸爸很忙。","ex_en":"Dad is busy.","tier":1,"family":"family","trap":"The second syllable is neutral: say bàba, not bàbà."},{"hanzi":"妈妈","pinyin":"māma","tones":"1 5","en":"mom, mother","pos":"noun","radical":"女","strokes":6,"ex_zh":"妈妈爱我。","ex_en":"Mom loves me.","tier":1,"family":"family","trap":"The second syllable is neutral: māma, not māmā."},{"hanzi":"哥哥","pinyin":"gēge","tones":"1 5","en":"older brother","pos":"noun","radical":"口","strokes":10,"ex_zh":"哥哥很高。","ex_en":"My older brother is tall.","tier":1,"family":"family","trap":"Neutral second syllable; 哥哥 is only an older brother."},{"hanzi":"弟弟","pinyin":"dìdi","tones":"4 5","en":"younger brother","pos":"noun","radical":"弓","strokes":7,"ex_zh":"弟弟哭了。","ex_en":"My little brother cried.","tier":1,"family":"family","trap":"Neutral second syllable; 弟弟 is younger, 哥哥 is older."},{"hanzi":"姐姐","pinyin":"jiějie","tones":"3 5","en":"older sister","pos":"noun","radical":"女","strokes":8,"ex_zh":"姐姐会弹琴。","ex_en":"My older sister can play the piano.","tier":1,"family":"family","trap":"Neutral second syllable; 姐姐 is older, 妹妹 is younger."},{"hanzi":"妹妹","pinyin":"mèimei","tones":"4 5","en":"younger sister","pos":"noun","radical":"女","strokes":8,"ex_zh":"妹妹很可爱。","ex_en":"My little sister is cute.","tier":1,"family":"family","trap":"Neutral second syllable; 妹妹 is a younger sister only."},{"hanzi":"家","pinyin":"jiā","tones":"1","en":"home, family","pos":"noun","radical":"宀","strokes":10,"ex_zh":"我家有四口人。","ex_en":"There are four people in my family.","tier":1,"family":"family","trap":"First tone, and j is unaspirated; do not say 'chee-ah'."},{"hanzi":"爷爷","pinyin":"yéye","tones":"2 5","en":"grandpa (father's side)","pos":"noun","radical":"父","strokes":6,"ex_zh":"爷爷喝茶。","ex_en":"Grandpa drinks tea.","tier":1,"family":"family","trap":"Neutral second syllable; 爷爷 is the father's father."},{"hanzi":"奶奶","pinyin":"nǎinai","tones":"3 5","en":"grandma (father's side)","pos":"noun","radical":"女","strokes":5,"ex_zh":"奶奶做饭。","ex_en":"Grandma cooks.","tier":1,"family":"family","trap":"Neutral second syllable; 奶奶 is the father's mother."},{"hanzi":"儿子","pinyin":"érzi","tones":"2 5","en":"son","pos":"noun","radical":"儿","strokes":2,"ex_zh":"他有一个儿子。","ex_en":"He has a son.","tier":1,"family":"family","trap":"子 is neutral here; the full reading zǐ means 'child' in other words."},{"hanzi":"女儿","pinyin":"nǚ'ér","tones":"3 2","en":"daughter","pos":"noun","radical":"女","strokes":3,"ex_zh":"她是我的女儿。","ex_en":"She is my daughter.","tier":1,"family":"family","trap":"Two syllables, not one: nǚ-ér, with a break between them."},{"hanzi":"孩子","pinyin":"háizi","tones":"2 5","en":"child","pos":"noun","radical":"子","strokes":9,"ex_zh":"孩子笑了。","ex_en":"The child smiled.","tier":1,"family":"family","trap":"Neutral second syllable; 子 here is a suffix, not 'son'."},{"hanzi":"水","pinyin":"shuǐ","tones":"3","en":"water","pos":"noun","radical":"水","strokes":4,"ex_zh":"请给我水。","ex_en":"Please give me water.","tier":1,"family":"food","trap":"Third tone dips then rises; sh is retroflex, tongue curled back."},{"hanzi":"米饭","pinyin":"mǐfàn","tones":"3 4","en":"cooked rice","pos":"noun","radical":"米","strokes":6,"ex_zh":"我吃米饭。","ex_en":"I eat rice.","tier":1,"family":"food","trap":"饭 falls on the fourth tone; 米 is raw grain, 米饭 is cooked."},{"hanzi":"面条","pinyin":"miàntiáo","tones":"4 2","en":"noodles","pos":"noun","radical":"面","strokes":9,"ex_zh":"我爱吃面条。","ex_en":"I love eating noodles.","tier":1,"family":"food","trap":"Both syllables keep full tones; 条 rises, it is not neutral."},{"hanzi":"苹果","pinyin":"píngguǒ","tones":"2 3","en":"apple","pos":"noun","radical":"艹","strokes":8,"ex_zh":"苹果很甜。","ex_en":"The apple is sweet.","tier":1,"family":"food","trap":"The second syllable is third tone; do not flatten it."},{"hanzi":"鸡蛋","pinyin":"jīdàn","tones":"1 4","en":"egg","pos":"noun","radical":"鸟","strokes":7,"ex_zh":"我吃鸡蛋。","ex_en":"I eat eggs.","tier":1,"family":"food","trap":"蛋 falls; 鸡 alone is a chicken, 鸡蛋 is the egg."},{"hanzi":"牛奶","pinyin":"niúnǎi","tones":"2 3","en":"milk","pos":"noun","radical":"牛","strokes":4,"ex_zh":"我喝牛奶。","ex_en":"I drink milk.","tier":1,"family":"food","trap":"Pitch rises then dips: 牛 is second tone, 奶 is third."},{"hanzi":"面包","pinyin":"miànbāo","tones":"4 1","en":"bread","pos":"noun","radical":"面","strokes":9,"ex_zh":"我买面包。","ex_en":"I buy bread.","tier":1,"family":"food","trap":"包 is first tone, high and flat; do not say bào."},{"hanzi":"茶","pinyin":"chá","tones":"2","en":"tea","pos":"noun","radical":"艹","strokes":9,"ex_zh":"我喝绿茶。","ex_en":"I drink green tea.","tier":1,"family":"food","trap":"Second tone rises; ch is aspirated, unlike zh."},{"hanzi":"肉","pinyin":"ròu","tones":"4","en":"meat","pos":"noun","radical":"肉","strokes":6,"ex_zh":"我不吃肉。","ex_en":"I do not eat meat.","tier":1,"family":"food","trap":"Fourth tone; r has the tongue curled back, not the English r."},{"hanzi":"鱼","pinyin":"yú","tones":"2","en":"fish","pos":"noun","radical":"鱼","strokes":8,"ex_zh":"鱼在水里。","ex_en":"The fish is in the water.","tier":1,"family":"food","trap":"After y the ü is written u but still sounds like the German ü."},{"hanzi":"菜","pinyin":"cài","tones":"4","en":"vegetables; dish of food","pos":"noun","radical":"艹","strokes":11,"ex_zh":"菜很好吃。","ex_en":"The food is tasty.","tier":1,"family":"food","trap":"Fourth tone; 菜 means both vegetables and a cooked dish."},{"hanzi":"糖","pinyin":"táng","tones":"2","en":"sugar, candy","pos":"noun","radical":"米","strokes":16,"ex_zh":"糖很甜。","ex_en":"Sugar is sweet.","tier":1,"family":"food","trap":"t is aspirated, unlike d; keep the final -ng."},{"hanzi":"汤","pinyin":"tāng","tones":"1","en":"soup","pos":"noun","radical":"氵","strokes":6,"ex_zh":"汤很热。","ex_en":"The soup is hot.","tier":1,"family":"food","trap":"First tone, and do not drop the final g."},{"hanzi":"西瓜","pinyin":"xīguā","tones":"1 1","en":"watermelon","pos":"noun","radical":"襾","strokes":6,"ex_zh":"西瓜很甜。","ex_en":"Watermelon is sweet.","tier":1,"family":"food","trap":"Both syllables are first tone; keep both high and flat."},{"hanzi":"你好","pinyin":"nǐ hǎo","tones":"3 3","en":"hello","pos":"phrase","radical":"亻","strokes":7,"ex_zh":"你好，老师！","ex_en":"Hello, teacher!","tier":1,"family":"greetings","trap":"Two third tones in a row: the first is spoken as second tone, so it sounds like ní hǎo."},{"hanzi":"再见","pinyin":"zàijiàn","tones":"4 4","en":"goodbye","pos":"phrase","radical":"冂","strokes":6,"ex_zh":"明天再见。","ex_en":"See you tomorrow.","tier":1,"family":"greetings","trap":"Both syllables fall; do not say zài flat."},{"hanzi":"谢谢","pinyin":"xièxie","tones":"4 5","en":"thank you","pos":"phrase","radical":"讠","strokes":12,"ex_zh":"谢谢你！","ex_en":"Thank you!","tier":1,"family":"greetings","trap":"Second syllable is neutral: xièxie, not xièxiè."},{"hanzi":"对不起","pinyin":"duìbuqǐ","tones":"4 5 3","en":"sorry","pos":"phrase","radical":"寸","strokes":5,"ex_zh":"对不起，我迟到了。","ex_en":"Sorry, I am late.","tier":1,"family":"greetings","trap":"In speech 不 before a fourth tone becomes second tone, so it sounds like duì bú qǐ."},{"hanzi":"不客气","pinyin":"búkèqi","tones":"2 4 5","en":"you are welcome","pos":"phrase","radical":"一","strokes":4,"ex_zh":"不客气！","ex_en":"You are welcome!","tier":1,"family":"greetings","trap":"不 is second tone here because 客 is fourth; written bù, said bú."},{"hanzi":"请","pinyin":"qǐng","tones":"3","en":"please","pos":"verb","radical":"讠","strokes":10,"ex_zh":"请坐。","ex_en":"Please sit.","tier":1,"family":"greetings","trap":"Third tone; q is aspirated, unlike j."},{"hanzi":"是","pinyin":"shì","tones":"4","en":"to be; yes","pos":"verb","radical":"日","strokes":9,"ex_zh":"我是学生。","ex_en":"I am a student.","tier":1,"family":"verbs","trap":"Used to link two nouns; do not use it before an adjective the way English 'is' works."},{"hanzi":"有","pinyin":"yǒu","tones":"3","en":"to have; there is","pos":"verb","radical":"月","strokes":6,"ex_zh":"我有一只猫。","ex_en":"I have a cat.","tier":1,"family":"verbs","trap":"Its negative is 没有, never 不有."},{"hanzi":"去","pinyin":"qù","tones":"4","en":"to go","pos":"verb","radical":"厶","strokes":5,"ex_zh":"我去学校。","ex_en":"I go to school.","tier":1,"family":"verbs","trap":"q is aspirated and the ü is rounded; do not say 'chee'."},{"hanzi":"来","pinyin":"lái","tones":"2","en":"to come","pos":"verb","radical":"木","strokes":7,"ex_zh":"请来这里。","ex_en":"Please come here.","tier":1,"family":"verbs","trap":"Second tone rises; it is the opposite of 去 qù, not a synonym."},{"hanzi":"看","pinyin":"kàn","tones":"4","en":"to look, to watch, to read","pos":"verb","radical":"目","strokes":9,"ex_zh":"我看书。","ex_en":"I read a book.","tier":1,"family":"verbs","trap":"Covers 'watch' and 'read' too; 看 is not only 'look at'."},{"hanzi":"吃","pinyin":"chī","tones":"1","en":"to eat","pos":"verb","radical":"口","strokes":6,"ex_zh":"我吃饭。","ex_en":"I eat a meal.","tier":1,"family":"verbs","trap":"Retroflex ch, first tone; do not say 'tsz'."},{"hanzi":"喝","pinyin":"hē","tones":"1","en":"to drink","pos":"verb","radical":"口","strokes":12,"ex_zh":"我喝水。","ex_en":"I drink water.","tier":1,"family":"verbs","trap":"First tone; h is breathy, not silent as in some English words."},{"hanzi":"说","pinyin":"shuō","tones":"1","en":"to speak, to say","pos":"verb","radical":"讠","strokes":9,"ex_zh":"他说中文。","ex_en":"He speaks Chinese.","tier":1,"family":"verbs","trap":"sh is retroflex; the final uo glides, it is not 'sho'."},{"hanzi":"做","pinyin":"zuò","tones":"4","en":"to do, to make","pos":"verb","radical":"亻","strokes":11,"ex_zh":"你在做什么？","ex_en":"What are you doing?","tier":1,"family":"verbs","trap":"z is unaspirated, closer to 'dz'; do not say 'zoo-oh'."},{"hanzi":"买","pinyin":"mǎi","tones":"3","en":"to buy","pos":"verb","radical":"乙","strokes":6,"ex_zh":"我买水果。","ex_en":"I buy fruit.","tier":1,"family":"verbs","trap":"Do not confuse with 卖 mài, to sell; the tone is the only difference."},{"hanzi":"走","pinyin":"zǒu","tones":"3","en":"to walk, to go","pos":"verb","radical":"走","strokes":7,"ex_zh":"我们走吧。","ex_en":"Let us go.","tier":1,"family":"verbs","trap":"Third tone; 走 is walking, 跑 pǎo is running."},{"hanzi":"跑","pinyin":"pǎo","tones":"3","en":"to run","pos":"verb","radical":"足","strokes":12,"ex_zh":"他跑得很快。","ex_en":"He runs very fast.","tier":1,"family":"verbs","trap":"p is aspirated, unlike b; third tone dips."},{"hanzi":"坐","pinyin":"zuò","tones":"4","en":"to sit","pos":"verb","radical":"土","strokes":7,"ex_zh":"请坐这里。","ex_en":"Please sit here.","tier":1,"family":"verbs","trap":"Same sound as 做 zuò, to do; the character carries the meaning."},{"hanzi":"站","pinyin":"zhàn","tones":"4","en":"to stand; a station","pos":"verb","radical":"立","strokes":10,"ex_zh":"请站起来。","ex_en":"Please stand up.","tier":1,"family":"verbs","trap":"zh is retroflex and unaspirated; do not say 'chan'."},{"hanzi":"喜欢","pinyin":"xǐhuan","tones":"3 5","en":"to like","pos":"verb","radical":"口","strokes":12,"ex_zh":"我喜欢猫。","ex_en":"I like cats.","tier":1,"family":"verbs","trap":"Second syllable is neutral: xǐhuan, not xǐhuān."},{"hanzi":"爱","pinyin":"ài","tones":"4","en":"to love","pos":"verb","radical":"爪","strokes":10,"ex_zh":"我爱妈妈。","ex_en":"I love mom.","tier":1,"family":"verbs","trap":"A single syllable starting with a vowel, so it sounds like 'eye' with a falling tone."},{"hanzi":"想","pinyin":"xiǎng","tones":"3","en":"to want, to think, to miss","pos":"verb","radical":"心","strokes":13,"ex_zh":"我想回家。","ex_en":"I want to go home.","tier":1,"family":"verbs","trap":"Three meanings in one word; 'miss someone' needs 想 with the person after it."},{"hanzi":"要","pinyin":"yào","tones":"4","en":"to want, to need","pos":"verb","radical":"襾","strokes":9,"ex_zh":"我要水。","ex_en":"I want water.","tier":1,"family":"verbs","trap":"Stronger than 想; 要 sounds like a demand, 想 is a wish."},{"hanzi":"会","pinyin":"huì","tones":"4","en":"can, to know how to","pos":"verb","radical":"人","strokes":6,"ex_zh":"我会游泳。","ex_en":"I can swim.","tier":1,"family":"verbs","trap":"会 is a learned skill; 能 is physical ability or permission."},{"hanzi":"能","pinyin":"néng","tones":"2","en":"can, to be able to","pos":"verb","radical":"肉","strokes":10,"ex_zh":"你能来吗？","ex_en":"Can you come?","tier":1,"family":"verbs","trap":"Second tone rises; do not use 能 for a skill you learned, use 会."},{"hanzi":"知道","pinyin":"zhīdao","tones":"1 5","en":"to know","pos":"verb","radical":"矢","strokes":8,"ex_zh":"我知道答案。","ex_en":"I know the answer.","tier":1,"family":"verbs","trap":"Second syllable neutral; 知道 is knowing a fact, not knowing a person."},{"hanzi":"叫","pinyin":"jiào","tones":"4","en":"to be called; to call","pos":"verb","radical":"口","strokes":5,"ex_zh":"我叫小明。","ex_en":"My name is Xiaoming.","tier":1,"family":"verbs","trap":"j is unaspirated; 叫 asks for a name, 说 is to speak."},{"hanzi":"玩","pinyin":"wán","tones":"2","en":"to play","pos":"verb","radical":"王","strokes":8,"ex_zh":"我们去玩。","ex_en":"Let us go play.","tier":1,"family":"verbs","trap":"Second tone; the w is a light glide, not the English v."},{"hanzi":"写","pinyin":"xiě","tones":"3","en":"to write","pos":"verb","radical":"冖","strokes":5,"ex_zh":"我写字。","ex_en":"I write characters.","tier":1,"family":"verbs","trap":"x is a soft 'sh'; do not say 'ks'."},{"hanzi":"睡觉","pinyin":"shuìjiào","tones":"4 4","en":"to sleep","pos":"verb","radical":"目","strokes":13,"ex_zh":"我要睡觉。","ex_en":"I want to sleep.","tier":1,"family":"verbs","trap":"Both syllables fall; 睡 alone is the verb, 觉 is neutral in some speech."},{"hanzi":"起床","pinyin":"qǐchuáng","tones":"3 2","en":"to get up (from bed)","pos":"verb","radical":"走","strokes":10,"ex_zh":"我七点起床。","ex_en":"I get up at seven.","tier":1,"family":"verbs","trap":"A fixed pair; 起 is third tone, 床 rises."},{"hanzi":"上学","pinyin":"shàngxué","tones":"4 2","en":"to go to school","pos":"verb","radical":"一","strokes":3,"ex_zh":"我每天上学。","ex_en":"I go to school every day.","tier":1,"family":"verbs","trap":"上 means 'up/on'; 上学 is the whole phrase, not 'up school'."},{"hanzi":"回家","pinyin":"huíjiā","tones":"2 2","en":"to go home","pos":"verb","radical":"囗","strokes":6,"ex_zh":"我要回家。","ex_en":"I want to go home.","tier":1,"family":"verbs","trap":"Both syllables rise; do not say huìjiā."},{"hanzi":"个","pinyin":"gè","tones":"4","en":"general measure word","pos":"measure","radical":"丨","strokes":3,"ex_zh":"三个人。","ex_en":"Three people.","tier":1,"family":"measure","trap":"The default measure word; it is not used for flat sheets or long thin things."},{"hanzi":"本","pinyin":"běn","tones":"3","en":"measure word for books","pos":"measure","radical":"木","strokes":5,"ex_zh":"一本书。","ex_en":"One book.","tier":1,"family":"measure","trap":"Third tone; use it for books and notebooks, not for sheets of paper."},{"hanzi":"只","pinyin":"zhī","tones":"1","en":"measure word for animals","pos":"measure","radical":"口","strokes":5,"ex_zh":"一只猫。","ex_en":"One cat.","tier":1,"family":"measure","trap":"For most animals; do not use 个 with a cat or dog."},{"hanzi":"条","pinyin":"tiáo","tones":"2","en":"measure word for long things","pos":"measure","radical":"木","strokes":7,"ex_zh":"一条鱼。","ex_en":"One fish.","tier":1,"family":"measure","trap":"For long, flexible things: fish, roads, trousers — not for books."},{"hanzi":"杯","pinyin":"bēi","tones":"1","en":"cup; measure word for drinks","pos":"measure","radical":"木","strokes":8,"ex_zh":"一杯茶。","ex_en":"A cup of tea.","tier":1,"family":"measure","trap":"First tone; it is both the noun 'cup' and the measure word for drinks."},{"hanzi":"老师","pinyin":"lǎoshī","tones":"3 1","en":"teacher","pos":"noun","radical":"老","strokes":6,"ex_zh":"老师来了。","ex_en":"The teacher has come.","tier":1,"family":"school","trap":"老 alone means 'old'; here it is only part of 'teacher'."},{"hanzi":"学生","pinyin":"xuésheng","tones":"2 5","en":"student","pos":"noun","radical":"子","strokes":8,"ex_zh":"我是学生。","ex_en":"I am a student.","tier":1,"family":"school","trap":"Second syllable neutral: xuésheng, not xuésheng with a full tone."},{"hanzi":"朋友","pinyin":"péngyou","tones":"2 5","en":"friend","pos":"noun","radical":"月","strokes":8,"ex_zh":"他是我的朋友。","ex_en":"He is my friend.","tier":1,"family":"school","trap":"Second syllable neutral: péngyou, not péngyǒu."},{"hanzi":"医生","pinyin":"yīshēng","tones":"1 1","en":"doctor","pos":"noun","radical":"匸","strokes":7,"ex_zh":"我爸爸是医生。","ex_en":"My dad is a doctor.","tier":1,"family":"school","trap":"Both first tone; 生 here is a full tone, not neutral."},{"hanzi":"名字","pinyin":"míngzi","tones":"2 5","en":"name","pos":"noun","radical":"口","strokes":6,"ex_zh":"你叫什么名字？","ex_en":"What is your name?","tier":1,"family":"school","trap":"Second syllable neutral; 名 is second tone."},{"hanzi":"岁","pinyin":"suì","tones":"4","en":"years old","pos":"measure","radical":"山","strokes":6,"ex_zh":"我八岁。","ex_en":"I am eight years old.","tier":1,"family":"numbers","trap":"Used without 年: say 我八岁, never 我八岁年."},{"hanzi":"多少","pinyin":"duōshao","tones":"1 5","en":"how many, how much","pos":"phrase","radical":"夕","strokes":6,"ex_zh":"你有多少书？","ex_en":"How many books do you have?","tier":1,"family":"numbers","trap":"Second syllable neutral; 多少 asks for a number, 几 asks for a small one."},{"hanzi":"今天","pinyin":"jīntiān","tones":"1 1","en":"today","pos":"noun","radical":"人","strokes":4,"ex_zh":"今天很冷。","ex_en":"Today is cold.","tier":2,"family":"time","trap":"Both first tone; 天 is not neutral here."},{"hanzi":"明天","pinyin":"míngtiān","tones":"2 1","en":"tomorrow","pos":"noun","radical":"日","strokes":8,"ex_zh":"明天见。","ex_en":"See you tomorrow.","tier":2,"family":"time","trap":"明 is second tone and means 'bright'; 明天 is not 'bright sky' but tomorrow."},{"hanzi":"昨天","pinyin":"zuótiān","tones":"2 1","en":"yesterday","pos":"noun","radical":"日","strokes":9,"ex_zh":"昨天我病了。","ex_en":"Yesterday I was sick.","tier":2,"family":"time","trap":"zuó is second tone; do not say zuò, which is 'to sit'."},{"hanzi":"现在","pinyin":"xiànzài","tones":"4 4","en":"now","pos":"noun","radical":"王","strokes":8,"ex_zh":"现在几点？","ex_en":"What time is it now?","tier":2,"family":"time","trap":"Both syllables fall; 现在 is 'now', 正在 is the ongoing marker."},{"hanzi":"早上","pinyin":"zǎoshang","tones":"3 5","en":"morning","pos":"noun","radical":"日","strokes":6,"ex_zh":"早上好！","ex_en":"Good morning!","tier":2,"family":"time","trap":"Second syllable neutral; 上 here is a suffix, not 'up'."},{"hanzi":"晚上","pinyin":"wǎnshang","tones":"3 5","en":"evening, night","pos":"noun","radical":"日","strokes":11,"ex_zh":"晚上很安静。","ex_en":"The night is quiet.","tier":2,"family":"time","trap":"Neutral second syllable; 晚 alone is 'late'."},{"hanzi":"中午","pinyin":"zhōngwǔ","tones":"1 3","en":"noon","pos":"noun","radical":"丨","strokes":4,"ex_zh":"中午吃饭。","ex_en":"Eat at noon.","tier":2,"family":"time","trap":"Both full tones: zhōng wǔ; do not flatten the 午."},{"hanzi":"星期","pinyin":"xīngqī","tones":"1 1","en":"week","pos":"noun","radical":"日","strokes":9,"ex_zh":"星期一上课。","ex_en":"Class is on Monday.","tier":2,"family":"time","trap":"Both first tone; the week is 星期, Monday is 星期一."},{"hanzi":"月","pinyin":"yuè","tones":"4","en":"month; moon","pos":"noun","radical":"月","strokes":4,"ex_zh":"这个月很忙。","ex_en":"This month is busy.","tier":2,"family":"time","trap":"Fourth tone; the same word means moon and month."},{"hanzi":"年","pinyin":"nián","tones":"2","en":"year","pos":"noun","radical":"干","strokes":6,"ex_zh":"明年我十岁。","ex_en":"Next year I will be ten.","tier":2,"family":"time","trap":"Second tone; say 三年 for three years, no measure word needed."},{"hanzi":"小时","pinyin":"xiǎoshí","tones":"3 2","en":"hour","pos":"noun","radical":"小","strokes":3,"ex_zh":"等了一小时。","ex_en":"Waited for an hour.","tier":2,"family":"time","trap":"小时 is a length of time; 点 is the clock reading."},{"hanzi":"分钟","pinyin":"fēnzhōng","tones":"1 1","en":"minute","pos":"noun","radical":"刀","strokes":4,"ex_zh":"等五分钟。","ex_en":"Wait five minutes.","tier":2,"family":"time","trap":"Both first tone; 分 alone is 'to divide' or a fraction."},{"hanzi":"点","pinyin":"diǎn","tones":"3","en":"o'clock; a dot","pos":"measure","radical":"灬","strokes":9,"ex_zh":"现在三点。","ex_en":"It is three o'clock.","tier":2,"family":"time","trap":"Third tone; for clock time use 点, not 小时."},{"hanzi":"时间","pinyin":"shíjiān","tones":"2 1","en":"time","pos":"noun","radical":"日","strokes":7,"ex_zh":"我没有时间。","ex_en":"I have no time.","tier":2,"family":"time","trap":"时间 is time in general; 时候 is 'when' in a phrase."},{"hanzi":"星期天","pinyin":"xīngqītiān","tones":"1 1 1","en":"Sunday","pos":"noun","radical":"日","strokes":9,"ex_zh":"星期天休息。","ex_en":"Rest on Sunday.","tier":2,"family":"time","trap":"Three syllables, all first tone; 星期天 and 星期日 both mean Sunday."},{"hanzi":"学校","pinyin":"xuéxiào","tones":"2 4","en":"school","pos":"noun","radical":"子","strokes":8,"ex_zh":"我去学校。","ex_en":"I go to school.","tier":2,"family":"school","trap":"x is soft; 校 falls on the fourth tone, not flat."},{"hanzi":"教室","pinyin":"jiàoshì","tones":"4 4","en":"classroom","pos":"noun","radical":"攵","strokes":11,"ex_zh":"教室很大。","ex_en":"The classroom is big.","tier":2,"family":"school","trap":"Both fourth tone; 教 is jiāo 'to teach' but jiào in 教室."},{"hanzi":"书","pinyin":"shū","tones":"1","en":"book","pos":"noun","radical":"乙","strokes":4,"ex_zh":"这本书很好。","ex_en":"This book is good.","tier":2,"family":"school","trap":"First tone; sh is retroflex and the vowel is tight."},{"hanzi":"笔","pinyin":"bǐ","tones":"3","en":"pen, pencil","pos":"noun","radical":"竹","strokes":10,"ex_zh":"我有三支笔。","ex_en":"I have three pens.","tier":2,"family":"school","trap":"Use 支 zhī as its measure word, not 个."},{"hanzi":"字","pinyin":"zì","tones":"4","en":"character, written word","pos":"noun","radical":"子","strokes":6,"ex_zh":"这个字很难。","ex_en":"This character is hard.","tier":2,"family":"school","trap":"z is unaspirated; 字 is a written character, 词 is a word."},{"hanzi":"课","pinyin":"kè","tones":"4","en":"lesson, class","pos":"noun","radical":"讠","strokes":10,"ex_zh":"我们上中文课。","ex_en":"We have Chinese class.","tier":2,"family":"school","trap":"Fourth tone; k is aspirated, unlike g."},{"hanzi":"问题","pinyin":"wèntí","tones":"4 2","en":"question, problem","pos":"noun","radical":"门","strokes":6,"ex_zh":"我有一个问题。","ex_en":"I have a question.","tier":2,"family":"school","trap":"Second syllable rises; 问 is 'to ask' alone."},{"hanzi":"作业","pinyin":"zuòyè","tones":"4 4","en":"homework","pos":"noun","radical":"亻","strokes":7,"ex_zh":"我做作业。","ex_en":"I do my homework.","tier":2,"family":"school","trap":"Both fall; 作业 is homework, 工作 is a job."},{"hanzi":"考试","pinyin":"kǎoshì","tones":"3 4","en":"exam","pos":"noun","radical":"老","strokes":6,"ex_zh":"明天有考试。","ex_en":"There is an exam tomorrow.","tier":2,"family":"school","trap":"考 is third tone; 考试 is the noun, 考 alone is the verb."},{"hanzi":"同学","pinyin":"tóngxué","tones":"2 2","en":"classmate","pos":"noun","radical":"口","strokes":6,"ex_zh":"他是我的同学。","ex_en":"He is my classmate.","tier":2,"family":"school","trap":"Both second tone; 同 means 'same', not 'with' on its own."},{"hanzi":"汉语","pinyin":"Hànyǔ","tones":"4 3","en":"Chinese language","pos":"noun","radical":"氵","strokes":5,"ex_zh":"我学汉语。","ex_en":"I study Chinese.","tier":2,"family":"school","trap":"语 is third tone; 汉语 is the spoken language, 中文 also works."},{"hanzi":"英语","pinyin":"Yīngyǔ","tones":"1 3","en":"English language","pos":"noun","radical":"艹","strokes":8,"ex_zh":"我会说英语。","ex_en":"I can speak English.","tier":2,"family":"school","trap":"Two full tones: Yīng yǔ; do not flatten the 语."},{"hanzi":"头","pinyin":"tóu","tones":"2","en":"head","pos":"noun","radical":"大","strokes":5,"ex_zh":"我头疼。","ex_en":"My head hurts.","tier":2,"family":"body","trap":"Second tone; 头 is also a suffix in 石头, 'stone'."},{"hanzi":"手","pinyin":"shǒu","tones":"3","en":"hand","pos":"noun","radical":"手","strokes":4,"ex_zh":"请举手。","ex_en":"Please raise your hand.","tier":2,"family":"body","trap":"Third tone; the final ou is a diphthong, not a plain 'o'."},{"hanzi":"眼睛","pinyin":"yǎnjing","tones":"3 5","en":"eye","pos":"noun","radical":"目","strokes":11,"ex_zh":"她的眼睛很大。","ex_en":"Her eyes are big.","tier":2,"family":"body","trap":"Second syllable neutral; 睛 is not jīng here."},{"hanzi":"耳朵","pinyin":"ěrduo","tones":"3 5","en":"ear","pos":"noun","radical":"耳","strokes":6,"ex_zh":"我的耳朵疼。","ex_en":"My ear hurts.","tier":2,"family":"body","trap":"Second syllable neutral: ěrduo, not ěrdǒu."},{"hanzi":"嘴","pinyin":"zuǐ","tones":"3","en":"mouth","pos":"noun","radical":"口","strokes":16,"ex_zh":"张开嘴。","ex_en":"Open your mouth.","tier":2,"family":"body","trap":"Third tone; the final ui is said like 'way', not 'oo-ee'."},{"hanzi":"鼻子","pinyin":"bízi","tones":"2 5","en":"nose","pos":"noun","radical":"鼻","strokes":14,"ex_zh":"我的鼻子红。","ex_en":"My nose is red.","tier":2,"family":"body","trap":"Second syllable neutral; 鼻 alone is second tone."},{"hanzi":"脚","pinyin":"jiǎo","tones":"3","en":"foot","pos":"noun","radical":"肉","strokes":11,"ex_zh":"我的脚冷。","ex_en":"My feet are cold.","tier":2,"family":"body","trap":"Third tone; j is unaspirated, unlike q."},{"hanzi":"牙","pinyin":"yá","tones":"2","en":"tooth","pos":"noun","radical":"牙","strokes":4,"ex_zh":"我的牙疼。","ex_en":"My tooth hurts.","tier":2,"family":"body","trap":"Second tone; 牙齿 yáchǐ is the fuller word for teeth."},{"hanzi":"头发","pinyin":"tóufa","tones":"2 5","en":"hair (on the head)","pos":"noun","radical":"大","strokes":5,"ex_zh":"她的头发很长。","ex_en":"Her hair is long.","tier":2,"family":"body","trap":"Second syllable neutral; 发 is fā 'to send' on its own."},{"hanzi":"脸","pinyin":"liǎn","tones":"3","en":"face","pos":"noun","radical":"肉","strokes":11,"ex_zh":"他的脸红了。","ex_en":"His face went red.","tier":2,"family":"body","trap":"Third tone; the 月 radical here means flesh, not moon."},{"hanzi":"房子","pinyin":"fángzi","tones":"2 5","en":"house","pos":"noun","radical":"户","strokes":8,"ex_zh":"我家房子很小。","ex_en":"My house is small.","tier":2,"family":"nature","trap":"Second syllable neutral; 房 alone is 'room' in 厨房."},{"hanzi":"门","pinyin":"mén","tones":"2","en":"door, gate","pos":"noun","radical":"门","strokes":3,"ex_zh":"请关门。","ex_en":"Please close the door.","tier":2,"family":"nature","trap":"Second tone; 门 is a door, 门口 is the doorway."},{"hanzi":"窗户","pinyin":"chuānghu","tones":"1 5","en":"window","pos":"noun","radical":"穴","strokes":12,"ex_zh":"请开窗户。","ex_en":"Please open the window.","tier":2,"family":"nature","trap":"Second syllable neutral: chuānghu, not chuānghù."},{"hanzi":"桌子","pinyin":"zhuōzi","tones":"1 5","en":"table, desk","pos":"noun","radical":"木","strokes":10,"ex_zh":"桌子上有书。","ex_en":"There are books on the table.","tier":2,"family":"nature","trap":"Second syllable neutral; 子 is a noun suffix here."},{"hanzi":"椅子","pinyin":"yǐzi","tones":"3 5","en":"chair","pos":"noun","radical":"木","strokes":12,"ex_zh":"请坐椅子。","ex_en":"Please sit on the chair.","tier":2,"family":"nature","trap":"Neutral second syllable; 椅 is third tone alone."},{"hanzi":"床","pinyin":"chuáng","tones":"2","en":"bed","pos":"noun","radical":"广","strokes":7,"ex_zh":"我的床很软。","ex_en":"My bed is soft.","tier":2,"family":"nature","trap":"Second tone; chu is aspirated, unlike zhu."},{"hanzi":"天气","pinyin":"tiānqì","tones":"1 4","en":"weather","pos":"noun","radical":"大","strokes":4,"ex_zh":"今天天气很好。","ex_en":"The weather is nice today.","tier":2,"family":"nature","trap":"Both full tones: tiān qì; 气 falls, it is not neutral."},{"hanzi":"雨","pinyin":"yǔ","tones":"3","en":"rain","pos":"noun","radical":"雨","strokes":8,"ex_zh":"下雨了。","ex_en":"It is raining.","tier":2,"family":"nature","trap":"Third tone; 下雨 is the verb phrase, 雨 alone is the noun."},{"hanzi":"雪","pinyin":"xuě","tones":"3","en":"snow","pos":"noun","radical":"雨","strokes":11,"ex_zh":"下雪了。","ex_en":"It is snowing.","tier":2,"family":"nature","trap":"Third tone; x is a soft 'sh', not 'ks'."},{"hanzi":"风","pinyin":"fēng","tones":"1","en":"wind","pos":"noun","radical":"风","strokes":4,"ex_zh":"风很大。","ex_en":"The wind is strong.","tier":2,"family":"nature","trap":"First tone; keep the final -ng, which English speakers often drop."},{"hanzi":"云","pinyin":"yún","tones":"2","en":"cloud","pos":"noun","radical":"二","strokes":4,"ex_zh":"天上有云。","ex_en":"There are clouds in the sky.","tier":2,"family":"nature","trap":"Second tone; the ü after y is written u."},{"hanzi":"太阳","pinyin":"tàiyáng","tones":"4 2","en":"sun","pos":"noun","radical":"大","strokes":4,"ex_zh":"太阳出来了。","ex_en":"The sun has come out.","tier":2,"family":"nature","trap":"太 falls, 阳 rises; 太 alone means 'too'."},{"hanzi":"热","pinyin":"rè","tones":"4","en":"hot","pos":"adjective","radical":"灬","strokes":10,"ex_zh":"今天很热。","ex_en":"Today is very hot.","tier":2,"family":"adjectives","trap":"r is retroflex, not the English r; fourth tone falls."},{"hanzi":"冷","pinyin":"lěng","tones":"3","en":"cold","pos":"adjective","radical":"冫","strokes":7,"ex_zh":"水很冷。","ex_en":"The water is cold.","tier":2,"family":"adjectives","trap":"Third tone; keep the final -ng."},{"hanzi":"大","pinyin":"dà","tones":"4","en":"big","pos":"adjective","radical":"大","strokes":3,"ex_zh":"房子很大。","ex_en":"The house is big.","tier":2,"family":"adjectives","trap":"Fourth tone; d is unaspirated, closer to 'd' in 'dog' than 't'."},{"hanzi":"小","pinyin":"xiǎo","tones":"3","en":"small","pos":"adjective","radical":"小","strokes":3,"ex_zh":"猫很小。","ex_en":"The cat is small.","tier":2,"family":"adjectives","trap":"Third tone; x is soft, do not say 'siao'."},{"hanzi":"多","pinyin":"duō","tones":"1","en":"many, much","pos":"adjective","radical":"夕","strokes":6,"ex_zh":"人很多。","ex_en":"There are many people.","tier":2,"family":"adjectives","trap":"First tone; 多 is an adjective, 多少 is 'how many'."},{"hanzi":"少","pinyin":"shǎo","tones":"3","en":"few, little","pos":"adjective","radical":"小","strokes":4,"ex_zh":"钱很少。","ex_en":"There is very little money.","tier":2,"family":"adjectives","trap":"Third tone; do not confuse with 小 xiǎo, small."},{"hanzi":"好","pinyin":"hǎo","tones":"3","en":"good, well","pos":"adjective","radical":"女","strokes":6,"ex_zh":"这个很好。","ex_en":"This one is good.","tier":2,"family":"adjectives","trap":"Third tone dips; in 你好 it becomes second tone before another third."},{"hanzi":"坏","pinyin":"huài","tones":"4","en":"bad, broken","pos":"adjective","radical":"土","strokes":7,"ex_zh":"手机坏了。","ex_en":"The phone is broken.","tier":2,"family":"adjectives","trap":"Fourth tone; hu is breathy, not like English 'w'."},{"hanzi":"高","pinyin":"gāo","tones":"1","en":"tall, high","pos":"adjective","radical":"高","strokes":10,"ex_zh":"他很高。","ex_en":"He is tall.","tier":2,"family":"adjectives","trap":"First tone; g is unaspirated, unlike k."},{"hanzi":"矮","pinyin":"ǎi","tones":"3","en":"short (of a person)","pos":"adjective","radical":"矢","strokes":13,"ex_zh":"弟弟很矮。","ex_en":"My little brother is short.","tier":2,"family":"adjectives","trap":"Third tone; use 矮 for people, 短 for objects."},{"hanzi":"长","pinyin":"cháng","tones":"2","en":"long","pos":"adjective","radical":"长","strokes":4,"ex_zh":"头发很长。","ex_en":"Her hair is long.","tier":2,"family":"adjectives","trap":"Second tone here; 长 zhǎng means 'to grow' in other words."},{"hanzi":"短","pinyin":"duǎn","tones":"3","en":"short (of things)","pos":"adjective","radical":"矢","strokes":12,"ex_zh":"裤子太短。","ex_en":"The trousers are too short.","tier":2,"family":"adjectives","trap":"Third tone; 短 is for length, 矮 for height of people."},{"hanzi":"快","pinyin":"kuài","tones":"4","en":"fast","pos":"adjective","radical":"忄","strokes":7,"ex_zh":"他跑得快。","ex_en":"He runs fast.","tier":2,"family":"adjectives","trap":"Fourth tone; 快 is fast, 块 kuài is a measure word for money."},{"hanzi":"慢","pinyin":"màn","tones":"4","en":"slow","pos":"adjective","radical":"忄","strokes":14,"ex_zh":"请慢一点。","ex_en":"Please go a little slower.","tier":2,"family":"adjectives","trap":"Fourth tone; the final is -an, not -ang."},{"hanzi":"新","pinyin":"xīn","tones":"1","en":"new","pos":"adjective","radical":"斤","strokes":13,"ex_zh":"这是我的新书。","ex_en":"This is my new book.","tier":2,"family":"adjectives","trap":"First tone; x is soft, do not say 'sin'."},{"hanzi":"旧","pinyin":"jiù","tones":"4","en":"old (of things)","pos":"adjective","radical":"日","strokes":5,"ex_zh":"这是旧衣服。","ex_en":"These are old clothes.","tier":2,"family":"adjectives","trap":"Fourth tone; 旧 is old things, 老 lǎo is old people."},{"hanzi":"漂亮","pinyin":"piàoliang","tones":"4 5","en":"pretty, beautiful","pos":"adjective","radical":"氵","strokes":14,"ex_zh":"她真漂亮。","ex_en":"She is really pretty.","tier":2,"family":"adjectives","trap":"Second syllable neutral: piàoliang, not piàoliàng."},{"hanzi":"干净","pinyin":"gānjìng","tones":"1 4","en":"clean","pos":"adjective","radical":"干","strokes":3,"ex_zh":"房间很干净。","ex_en":"The room is clean.","tier":2,"family":"adjectives","trap":"净 falls on the fourth tone; do not flatten it."},{"hanzi":"忙","pinyin":"máng","tones":"2","en":"busy","pos":"adjective","radical":"忄","strokes":6,"ex_zh":"爸爸很忙。","ex_en":"Dad is busy.","tier":2,"family":"adjectives","trap":"Second tone; keep the final -ng."},{"hanzi":"累","pinyin":"lèi","tones":"4","en":"tired","pos":"adjective","radical":"糸","strokes":11,"ex_zh":"我很累。","ex_en":"I am very tired.","tier":2,"family":"adjectives","trap":"Fourth tone; do not say 'lay' with a flat pitch."},{"hanzi":"狗","pinyin":"gǒu","tones":"3","en":"dog","pos":"noun","radical":"犭","strokes":8,"ex_zh":"我有一只狗。","ex_en":"I have a dog.","tier":2,"family":"nature","trap":"Third tone; the measure word is 只, not 个."},{"hanzi":"猫","pinyin":"māo","tones":"1","en":"cat","pos":"noun","radical":"犭","strokes":11,"ex_zh":"猫在睡觉。","ex_en":"The cat is sleeping.","tier":2,"family":"nature","trap":"First tone; the measure word is 只, not 个."},{"hanzi":"鸟","pinyin":"niǎo","tones":"3","en":"bird","pos":"noun","radical":"鸟","strokes":5,"ex_zh":"鸟在飞。","ex_en":"The bird is flying.","tier":2,"family":"nature","trap":"Third tone; the final -ao glides, it is not 'nee-ow'."},{"hanzi":"树","pinyin":"shù","tones":"4","en":"tree","pos":"noun","radical":"木","strokes":9,"ex_zh":"树很高。","ex_en":"The tree is tall.","tier":2,"family":"nature","trap":"Fourth tone; sh is retroflex, tongue curled back."},{"hanzi":"花","pinyin":"huā","tones":"1","en":"flower","pos":"noun","radical":"艹","strokes":7,"ex_zh":"花很香。","ex_en":"The flowers smell sweet.","tier":2,"family":"nature","trap":"First tone; hu is breathy, not like English 'w'."},{"hanzi":"工作","pinyin":"gōngzuò","tones":"1 4","en":"work, job","pos":"noun","radical":"工","strokes":3,"ex_zh":"爸爸工作很忙。","ex_en":"Dad is busy with work.","tier":2,"family":"verbs","trap":"Both syllables full: gōng zuò; 作 falls, it is not neutral."},{"hanzi":"电影","pinyin":"diànyǐng","tones":"4 3","en":"movie","pos":"noun","radical":"田","strokes":5,"ex_zh":"我们看电影。","ex_en":"We watch a movie.","tier":2,"family":"school","trap":"影 is third tone; 电影 uses 看, not 见."},{"hanzi":"音乐","pinyin":"yīnyuè","tones":"1 4","en":"music","pos":"noun","radical":"音","strokes":9,"ex_zh":"我喜欢音乐。","ex_en":"I like music.","tier":2,"family":"school","trap":"乐 is yuè for music but lè for happy; the reading changes with meaning."},{"hanzi":"画画","pinyin":"huàhuà","tones":"4 4","en":"to draw, to paint","pos":"verb","radical":"田","strokes":8,"ex_zh":"我喜欢画画。","ex_en":"I like to draw.","tier":2,"family":"verbs","trap":"Both syllables fall; the first 画 is the verb, the second the noun."},{"hanzi":"唱歌","pinyin":"chànggē","tones":"4 1","en":"to sing","pos":"verb","radical":"口","strokes":11,"ex_zh":"她唱歌很好听。","ex_en":"She sings beautifully.","tier":2,"family":"verbs","trap":"唱 falls, 歌 is high and flat; do not flatten both."},{"hanzi":"跳舞","pinyin":"tiàowǔ","tones":"4 3","en":"to dance","pos":"verb","radical":"足","strokes":13,"ex_zh":"我们一起跳舞。","ex_en":"We dance together.","tier":2,"family":"verbs","trap":"舞 is third tone; 跳 alone means 'to jump'."},{"hanzi":"游泳","pinyin":"yóuyǒng","tones":"2 3","en":"to swim","pos":"verb","radical":"氵","strokes":12,"ex_zh":"我会游泳。","ex_en":"I can swim.","tier":2,"family":"verbs","trap":"Pitch rises then dips: yóu yǒng; 游 is not first tone."},{"hanzi":"足球","pinyin":"zúqiú","tones":"2 2","en":"soccer, football","pos":"noun","radical":"足","strokes":7,"ex_zh":"我们踢足球。","ex_en":"We play soccer.","tier":2,"family":"school","trap":"Both second tone; play soccer is 踢足球, not 打足球."},{"hanzi":"手机","pinyin":"shǒujī","tones":"3 1","en":"mobile phone","pos":"noun","radical":"手","strokes":4,"ex_zh":"我的手机没电。","ex_en":"My phone has no battery.","tier":2,"family":"nature","trap":"手 is third tone, 机 is first; 手机 is not 'hand machine' in use."},{"hanzi":"电脑","pinyin":"diànnǎo","tones":"4 3","en":"computer","pos":"noun","radical":"田","strokes":5,"ex_zh":"我用电脑学习。","ex_en":"I study on the computer.","tier":2,"family":"nature","trap":"脑 is third tone; 电脑 is literally 'electric brain'."},{"hanzi":"电视","pinyin":"diànshì","tones":"4 4","en":"television","pos":"noun","radical":"田","strokes":5,"ex_zh":"我看电视。","ex_en":"I watch TV.","tier":2,"family":"nature","trap":"Both fall; watch TV is 看电视, not 看电."},{"hanzi":"衣服","pinyin":"yīfu","tones":"1 5","en":"clothes","pos":"noun","radical":"衣","strokes":6,"ex_zh":"这件衣服好看。","ex_en":"This piece of clothing looks nice.","tier":2,"family":"nature","trap":"Second syllable neutral: yīfu, not yīfú."},{"hanzi":"裤子","pinyin":"kùzi","tones":"4 5","en":"trousers","pos":"noun","radical":"衤","strokes":12,"ex_zh":"这条裤子很长。","ex_en":"These trousers are long.","tier":2,"family":"nature","trap":"Measure word is 条, not 件; 子 is neutral."},{"hanzi":"鞋","pinyin":"xié","tones":"2","en":"shoe","pos":"noun","radical":"革","strokes":15,"ex_zh":"我的鞋很新。","ex_en":"My shoes are new.","tier":2,"family":"nature","trap":"Second tone; the measure word is 双 for a pair."},{"hanzi":"帽子","pinyin":"màozi","tones":"4 5","en":"hat","pos":"noun","radical":"巾","strokes":12,"ex_zh":"他戴着帽子。","ex_en":"He is wearing a hat.","tier":2,"family":"nature","trap":"Neutral second syllable; 戴 is used for hats, not 穿."},{"hanzi":"红","pinyin":"hóng","tones":"2","en":"red","pos":"adjective","radical":"纟","strokes":6,"ex_zh":"苹果是红的。","ex_en":"The apple is red.","tier":2,"family":"adjectives","trap":"Second tone; keep the final -ng."},{"hanzi":"蓝","pinyin":"lán","tones":"2","en":"blue","pos":"adjective","radical":"艹","strokes":13,"ex_zh":"天空很蓝。","ex_en":"The sky is very blue.","tier":2,"family":"adjectives","trap":"Second tone; the final is -an, not -ang."},{"hanzi":"黄","pinyin":"huáng","tones":"2","en":"yellow","pos":"adjective","radical":"黄","strokes":11,"ex_zh":"香蕉是黄的。","ex_en":"Bananas are yellow.","tier":2,"family":"adjectives","trap":"Second tone; hu is breathy, not like English 'w'."},{"hanzi":"绿","pinyin":"lǜ","tones":"4","en":"green","pos":"adjective","radical":"纟","strokes":11,"ex_zh":"草是绿色的。","ex_en":"Grass is green.","tier":2,"family":"adjectives","trap":"lǜ has the ü sound, written u after l; do not say 'loo'."},{"hanzi":"白","pinyin":"bái","tones":"2","en":"white","pos":"adjective","radical":"白","strokes":5,"ex_zh":"雪是白的。","ex_en":"Snow is white.","tier":2,"family":"adjectives","trap":"Second tone; b is unaspirated, unlike p."},{"hanzi":"黑","pinyin":"hēi","tones":"1","en":"black","pos":"adjective","radical":"黑","strokes":12,"ex_zh":"我的猫很黑。","ex_en":"My cat is very black.","tier":2,"family":"adjectives","trap":"First tone; the final ei is a diphthong, not a plain 'e'."},{"hanzi":"早","pinyin":"zǎo","tones":"3","en":"early","pos":"adjective","radical":"日","strokes":6,"ex_zh":"你来得真早。","ex_en":"You came really early.","tier":2,"family":"time","trap":"Third tone; 早 is also 'good morning' in 早上好."},{"hanzi":"晚","pinyin":"wǎn","tones":"3","en":"late","pos":"adjective","radical":"日","strokes":11,"ex_zh":"今天很晚了。","ex_en":"It is very late today.","tier":2,"family":"time","trap":"Third tone; the w is a light glide, not English 'w'."},{"hanzi":"远","pinyin":"yuǎn","tones":"3","en":"far","pos":"adjective","radical":"辶","strokes":7,"ex_zh":"学校很远。","ex_en":"The school is far.","tier":2,"family":"adjectives","trap":"Third tone; the ü after y is written u."},{"hanzi":"近","pinyin":"jìn","tones":"4","en":"near","pos":"adjective","radical":"辶","strokes":7,"ex_zh":"我家很近。","ex_en":"My home is near.","tier":2,"family":"adjectives","trap":"Fourth tone; j is unaspirated, unlike q."},{"hanzi":"便宜","pinyin":"piányi","tones":"2 5","en":"cheap","pos":"adjective","radical":"亻","strokes":9,"ex_zh":"这个很便宜。","ex_en":"This one is cheap.","tier":2,"family":"adjectives","trap":"Second syllable neutral: piányi, not piányí."},{"hanzi":"高兴","pinyin":"gāoxìng","tones":"1 4","en":"happy","pos":"adjective","radical":"高","strokes":10,"ex_zh":"我很高兴。","ex_en":"I am very happy.","tier":3,"family":"adjectives","trap":"兴 falls on the fourth tone; the flat xīng is 'to rise'."},{"hanzi":"难过","pinyin":"nánguò","tones":"2 4","en":"sad","pos":"adjective","radical":"隹","strokes":10,"ex_zh":"他很难过。","ex_en":"He is very sad.","tier":3,"family":"adjectives","trap":"Literally 'hard to pass'; the meaning is emotional, not physical."},{"hanzi":"生气","pinyin":"shēngqì","tones":"1 4","en":"angry","pos":"adjective","radical":"生","strokes":5,"ex_zh":"妈妈生气了。","ex_en":"Mom got angry.","tier":3,"family":"adjectives","trap":"气 falls; 生气 is a verb phrase, not a noun."},{"hanzi":"害怕","pinyin":"hàipà","tones":"4 4","en":"afraid","pos":"adjective","radical":"宀","strokes":10,"ex_zh":"我很害怕。","ex_en":"I am very afraid.","tier":3,"family":"adjectives","trap":"Both syllables fall; 怕 alone is the verb 'to fear'."},{"hanzi":"担心","pinyin":"dānxīn","tones":"1 1","en":"to worry","pos":"verb","radical":"手","strokes":8,"ex_zh":"别担心。","ex_en":"Do not worry.","tier":3,"family":"verbs","trap":"Both first tone; 担心 takes the thing worried about after it."},{"hanzi":"觉得","pinyin":"juéde","tones":"2 5","en":"to feel, to think","pos":"verb","radical":"见","strokes":9,"ex_zh":"我觉得很好。","ex_en":"I think it is good.","tier":3,"family":"verbs","trap":"Second syllable neutral: juéde, not juédé."},{"hanzi":"希望","pinyin":"xīwàng","tones":"1 4","en":"to hope","pos":"verb","radical":"巾","strokes":7,"ex_zh":"我希望你来。","ex_en":"I hope you come.","tier":3,"family":"verbs","trap":"望 falls; 希 is first tone, high and flat."},{"hanzi":"帮助","pinyin":"bāngzhù","tones":"1 4","en":"to help","pos":"verb","radical":"巾","strokes":9,"ex_zh":"请帮助我。","ex_en":"Please help me.","tier":3,"family":"verbs","trap":"助 falls; 帮 alone is the same verb in speech."},{"hanzi":"告诉","pinyin":"gàosu","tones":"4 5","en":"to tell","pos":"verb","radical":"口","strokes":7,"ex_zh":"请告诉我。","ex_en":"Please tell me.","tier":3,"family":"verbs","trap":"Second syllable neutral: gàosu, not gàosù."},{"hanzi":"认识","pinyin":"rènshi","tones":"4 5","en":"to know (a person)","pos":"verb","radical":"讠","strokes":4,"ex_zh":"我认识他。","ex_en":"I know him.","tier":3,"family":"verbs","trap":"Second syllable neutral; use it for people, 知道 for facts."},{"hanzi":"开始","pinyin":"kāishǐ","tones":"1 3","en":"to begin","pos":"verb","radical":"廾","strokes":4,"ex_zh":"课开始了。","ex_en":"Class has started.","tier":3,"family":"verbs","trap":"始 is third tone; do not flatten it."},{"hanzi":"结束","pinyin":"jiéshù","tones":"2 4","en":"to end","pos":"verb","radical":"纟","strokes":9,"ex_zh":"比赛结束了。","ex_en":"The match is over.","tier":3,"family":"verbs","trap":"束 falls on the fourth tone; it is the opposite of 开始."},{"hanzi":"学习","pinyin":"xuéxí","tones":"2 2","en":"to study","pos":"verb","radical":"子","strokes":8,"ex_zh":"我学习中文。","ex_en":"I study Chinese.","tier":3,"family":"school","trap":"Both second tone; 习 is not neutral here."},{"hanzi":"练习","pinyin":"liànxí","tones":"4 2","en":"to practise","pos":"verb","radical":"纟","strokes":8,"ex_zh":"我练习写字。","ex_en":"I practise writing.","tier":3,"family":"school","trap":"练 falls, 习 rises; both tones are full."},{"hanzi":"记住","pinyin":"jìzhù","tones":"4 4","en":"to remember","pos":"verb","radical":"讠","strokes":5,"ex_zh":"请记住这个字。","ex_en":"Please remember this character.","tier":3,"family":"school","trap":"Both fall; 住 here is a result complement, not 'to live'."},{"hanzi":"忘记","pinyin":"wàngjì","tones":"4 4","en":"to forget","pos":"verb","radical":"心","strokes":7,"ex_zh":"我忘记名字了。","ex_en":"I forgot the name.","tier":3,"family":"school","trap":"Both fourth tone; 忘 is the verb, 记 is 'to record'."},{"hanzi":"明白","pinyin":"míngbai","tones":"2 5","en":"to understand","pos":"verb","radical":"日","strokes":8,"ex_zh":"我明白了。","ex_en":"I understand now.","tier":3,"family":"school","trap":"Second syllable neutral: míngbai, not míngbái."},{"hanzi":"回答","pinyin":"huídá","tones":"2 2","en":"to answer","pos":"verb","radical":"囗","strokes":6,"ex_zh":"请回答问题。","ex_en":"Please answer the question.","tier":3,"family":"school","trap":"Both second tone; 答 is dá here, not dā."},{"hanzi":"问","pinyin":"wèn","tones":"4","en":"to ask","pos":"verb","radical":"门","strokes":6,"ex_zh":"我问老师。","ex_en":"I ask the teacher.","tier":3,"family":"school","trap":"Fourth tone; 问 is to ask a question, 请 is to request."},{"hanzi":"带","pinyin":"dài","tones":"4","en":"to bring, to carry","pos":"verb","radical":"巾","strokes":9,"ex_zh":"请带书来。","ex_en":"Please bring a book.","tier":3,"family":"verbs","trap":"Fourth tone; 带 is to bring along, 拿 is to hold."},{"hanzi":"找","pinyin":"zhǎo","tones":"3","en":"to look for","pos":"verb","radical":"扌","strokes":7,"ex_zh":"我在找钥匙。","ex_en":"I am looking for the key.","tier":3,"family":"verbs","trap":"Third tone; zh is retroflex, not 'z'."},{"hanzi":"等","pinyin":"děng","tones":"3","en":"to wait","pos":"verb","radical":"竹","strokes":12,"ex_zh":"请等我。","ex_en":"Please wait for me.","tier":3,"family":"verbs","trap":"Third tone; keep the final -ng."},{"hanzi":"开","pinyin":"kāi","tones":"1","en":"to open","pos":"verb","radical":"廾","strokes":4,"ex_zh":"请开门。","ex_en":"Please open the door.","tier":3,"family":"verbs","trap":"First tone; k is aspirated, unlike g."},{"hanzi":"关","pinyin":"guān","tones":"1","en":"to close","pos":"verb","radical":"八","strokes":6,"ex_zh":"请关灯。","ex_en":"Please turn off the light.","tier":3,"family":"verbs","trap":"First tone; g is unaspirated, unlike k."},{"hanzi":"用","pinyin":"yòng","tones":"4","en":"to use","pos":"verb","radical":"用","strokes":5,"ex_zh":"我用筷子。","ex_en":"I use chopsticks.","tier":3,"family":"verbs","trap":"Fourth tone; keep the final -ng."},{"hanzi":"给","pinyin":"gěi","tones":"3","en":"to give","pos":"verb","radical":"纟","strokes":9,"ex_zh":"请给我书。","ex_en":"Please give me the book.","tier":3,"family":"verbs","trap":"Third tone; 给 takes the receiver before the thing."},{"hanzi":"送","pinyin":"sòng","tones":"4","en":"to give (a gift); to see off","pos":"verb","radical":"辶","strokes":9,"ex_zh":"我送你礼物。","ex_en":"I give you a gift.","tier":3,"family":"verbs","trap":"Fourth tone; 送 is a gift or escorting someone, 给 is plain giving."},{"hanzi":"帮忙","pinyin":"bāngmáng","tones":"1 2","en":"to help out","pos":"verb","radical":"巾","strokes":9,"ex_zh":"请你帮忙。","ex_en":"Please help out.","tier":3,"family":"verbs","trap":"忙 rises on the second tone; 帮忙 is intransitive, 帮助 takes an object."},{"hanzi":"火车站","pinyin":"huǒchēzhàn","tones":"3 1 4","en":"train station","pos":"noun","radical":"火","strokes":4,"ex_zh":"火车站在哪里？","ex_en":"Where is the train station?","tier":3,"family":"nature","trap":"Three syllables: huǒ chē zhàn; 车 is first tone, not neutral."},{"hanzi":"飞机","pinyin":"fēijī","tones":"1 1","en":"airplane","pos":"noun","radical":"飞","strokes":3,"ex_zh":"飞机很高。","ex_en":"The plane is high up.","tier":3,"family":"nature","trap":"Both first tone; 机 is not neutral."},{"hanzi":"自行车","pinyin":"zìxíngchē","tones":"4 2 1","en":"bicycle","pos":"noun","radical":"自","strokes":6,"ex_zh":"我骑自行车。","ex_en":"I ride a bicycle.","tier":3,"family":"nature","trap":"Three syllables: zì xíng chē; 行 is xíng 'to travel' here."},{"hanzi":"出租车","pinyin":"chūzūchē","tones":"1 1 1","en":"taxi","pos":"noun","radical":"凵","strokes":5,"ex_zh":"我们坐出租车。","ex_en":"We take a taxi.","tier":3,"family":"nature","trap":"All three first tone; 出 is 'to go out', 租 is 'to rent'."},{"hanzi":"公共汽车","pinyin":"gōnggòng qìchē","tones":"1 4 4 1","en":"bus","pos":"noun","radical":"八","strokes":4,"ex_zh":"我坐公共汽车。","ex_en":"I take the bus.","tier":3,"family":"nature","trap":"Four syllables; 共 falls, 车 stays first tone."},{"hanzi":"地图","pinyin":"dìtú","tones":"4 2","en":"map","pos":"noun","radical":"土","strokes":6,"ex_zh":"请看地图。","ex_en":"Please look at the map.","tier":3,"family":"nature","trap":"图 rises; 地 alone is 'ground' or 'earth'."},{"hanzi":"左边","pinyin":"zuǒbian","tones":"3 5","en":"left side","pos":"noun","radical":"工","strokes":5,"ex_zh":"学校在左边。","ex_en":"The school is on the left.","tier":3,"family":"nature","trap":"Second syllable neutral: zuǒbian, not zuǒbiān."},{"hanzi":"右边","pinyin":"yòubian","tones":"4 5","en":"right side","pos":"noun","radical":"口","strokes":5,"ex_zh":"商店在右边。","ex_en":"The shop is on the right.","tier":3,"family":"nature","trap":"Neutral second syllable; 右 falls, 左 dips."},{"hanzi":"前面","pinyin":"qiánmiàn","tones":"2 4","en":"in front","pos":"noun","radical":"刂","strokes":9,"ex_zh":"老师在前面。","ex_en":"The teacher is in front.","tier":3,"family":"nature","trap":"面 falls; 前面 is a place, 以前 is 'before' in time."},{"hanzi":"后面","pinyin":"hòumiàn","tones":"4 4","en":"behind","pos":"noun","radical":"口","strokes":6,"ex_zh":"我在后面。","ex_en":"I am behind.","tier":3,"family":"nature","trap":"Both fall; 后 is 'after', 候 in 时候 is neutral."},{"hanzi":"里面","pinyin":"lǐmiàn","tones":"3 4","en":"inside","pos":"noun","radical":"里","strokes":7,"ex_zh":"书在里面。","ex_en":"The book is inside.","tier":3,"family":"nature","trap":"里 is third tone; do not confuse with 李 lǐ, a surname."},{"hanzi":"外面","pinyin":"wàimiàn","tones":"4 4","en":"outside","pos":"noun","radical":"夕","strokes":5,"ex_zh":"外面很冷。","ex_en":"It is cold outside.","tier":3,"family":"nature","trap":"Both fall; 外 is 'outside', 处 is 'place'."},{"hanzi":"商店","pinyin":"shāngdiàn","tones":"1 4","en":"shop","pos":"noun","radical":"口","strokes":11,"ex_zh":"商店很远。","ex_en":"The shop is far.","tier":3,"family":"nature","trap":"店 falls; 商 is first tone, high and flat."},{"hanzi":"公园","pinyin":"gōngyuán","tones":"1 2","en":"park","pos":"noun","radical":"八","strokes":4,"ex_zh":"我们去公园。","ex_en":"We go to the park.","tier":3,"family":"nature","trap":"园 rises; 公园 is a public park, 花园 a garden."},{"hanzi":"已经","pinyin":"yǐjīng","tones":"3 1","en":"already","pos":"adverb","radical":"己","strokes":3,"ex_zh":"我已经吃了。","ex_en":"I have already eaten.","tier":3,"family":"time","trap":"经 is first tone, not neutral; 已 is third tone."},{"hanzi":"正在","pinyin":"zhèngzài","tones":"4 4","en":"in the middle of (doing)","pos":"adverb","radical":"止","strokes":5,"ex_zh":"他正在吃饭。","ex_en":"He is eating right now.","tier":3,"family":"time","trap":"Both fall; 正在 marks an action happening now, 现在 is the noun 'now'."},{"hanzi":"马上","pinyin":"mǎshàng","tones":"3 4","en":"right away","pos":"adverb","radical":"马","strokes":3,"ex_zh":"我马上来。","ex_en":"I am coming right away.","tier":3,"family":"time","trap":"Literally 'on horseback'; 上 falls, it is not neutral."},{"hanzi":"非常","pinyin":"fēicháng","tones":"1 2","en":"very, extremely","pos":"adverb","radical":"非","strokes":8,"ex_zh":"今天非常热。","ex_en":"Today is extremely hot.","tier":3,"family":"adjectives","trap":"常 rises; stronger than 很, which is the plain 'very'."},{"hanzi":"特别","pinyin":"tèbié","tones":"4 2","en":"especially","pos":"adverb","radical":"牛","strokes":10,"ex_zh":"这个特别大。","ex_en":"This one is especially big.","tier":3,"family":"adjectives","trap":"别 rises on the second tone; do not say biè."},{"hanzi":"一起","pinyin":"yìqǐ","tones":"4 3","en":"together","pos":"adverb","radical":"一","strokes":1,"ex_zh":"我们一起走。","ex_en":"We walk together.","tier":3,"family":"verbs","trap":"一 changes to second tone before a third tone, so it sounds like yí qǐ."},{"hanzi":"一定","pinyin":"yídìng","tones":"2 4","en":"certainly, definitely","pos":"adverb","radical":"一","strokes":1,"ex_zh":"你一定要来。","ex_en":"You must definitely come.","tier":3,"family":"verbs","trap":"一 becomes second tone before the falling 定, written yī but said yí."},{"hanzi":"当然","pinyin":"dāngrán","tones":"1 2","en":"of course","pos":"adverb","radical":"彐","strokes":6,"ex_zh":"当然可以。","ex_en":"Of course you can.","tier":3,"family":"greetings","trap":"然 rises; 当 is first tone, high and flat."},{"hanzi":"可能","pinyin":"kěnéng","tones":"3 2","en":"maybe, possible","pos":"adverb","radical":"口","strokes":5,"ex_zh":"他可能来。","ex_en":"He may come.","tier":3,"family":"verbs","trap":"Pitch dips then rises; 能 is second tone, not neutral."},{"hanzi":"应该","pinyin":"yīnggāi","tones":"1 1","en":"should","pos":"verb","radical":"广","strokes":7,"ex_zh":"你应该睡觉。","ex_en":"You should sleep.","tier":3,"family":"verbs","trap":"Both first tone; 该 is not neutral here."},{"hanzi":"必须","pinyin":"bìxū","tones":"4 1","en":"must","pos":"adverb","radical":"心","strokes":5,"ex_zh":"你必须洗手。","ex_en":"You must wash your hands.","tier":3,"family":"verbs","trap":"须 is first tone; stronger and more formal than 应该."},{"hanzi":"然后","pinyin":"ránhòu","tones":"2 4","en":"then, afterwards","pos":"adverb","radical":"灬","strokes":12,"ex_zh":"我先吃，然后走。","ex_en":"I eat first, then go.","tier":3,"family":"time","trap":"后 falls; 然后 comes after the first action in a sequence."},{"hanzi":"因为","pinyin":"yīnwèi","tones":"1 4","en":"because","pos":"phrase","radical":"囗","strokes":6,"ex_zh":"因为下雨，我不去。","ex_en":"Because it is raining, I am not going.","tier":3,"family":"time","trap":"为 falls here; 因为 pairs with 所以 in a sentence."},{"hanzi":"所以","pinyin":"suǒyǐ","tones":"3 3","en":"so, therefore","pos":"phrase","radical":"户","strokes":8,"ex_zh":"下雨，所以我没去。","ex_en":"It rained, so I did not go.","tier":3,"family":"time","trap":"Two third tones: 所 is spoken as second tone before 以."},{"hanzi":"但是","pinyin":"dànshì","tones":"4 4","en":"but","pos":"phrase","radical":"亻","strokes":7,"ex_zh":"我想去，但是很累。","ex_en":"I want to go, but I am tired.","tier":3,"family":"verbs","trap":"Both fall; 但是 is more formal than 可是."},{"hanzi":"如果","pinyin":"rúguǒ","tones":"2 3","en":"if","pos":"phrase","radical":"女","strokes":6,"ex_zh":"如果下雨，我不去。","ex_en":"If it rains, I am not going.","tier":3,"family":"time","trap":"果 is third tone; 如果 pairs with 就 in the second clause."},{"hanzi":"还是","pinyin":"háishi","tones":"2 5","en":"or; still","pos":"phrase","radical":"辶","strokes":7,"ex_zh":"你喝茶还是水？","ex_en":"Tea or water?","tier":3,"family":"verbs","trap":"Second syllable neutral; 还是 offers a choice, 或者 states one."},{"hanzi":"或者","pinyin":"huòzhě","tones":"4 3","en":"or (in a statement)","pos":"phrase","radical":"戈","strokes":8,"ex_zh":"茶或者水都行。","ex_en":"Tea or water is fine.","tier":3,"family":"verbs","trap":"者 is third tone; 或者 is for statements, 还是 for questions."},{"hanzi":"每","pinyin":"měi","tones":"3","en":"every, each","pos":"adjective","radical":"毋","strokes":7,"ex_zh":"我每天跑步。","ex_en":"I run every day.","tier":3,"family":"time","trap":"Third tone; 每 needs a measure word: 每天, 每个."},{"hanzi":"都","pinyin":"dōu","tones":"1","en":"all, both","pos":"adverb","radical":"阝","strokes":10,"ex_zh":"我们都喜欢。","ex_en":"We all like it.","tier":3,"family":"verbs","trap":"First tone; 都 goes after the subject and before the verb, never first."},{"hanzi":"也","pinyin":"yě","tones":"3","en":"also, too","pos":"adverb","radical":"乙","strokes":3,"ex_zh":"我也喜欢。","ex_en":"I like it too.","tier":3,"family":"verbs","trap":"Third tone; 也 comes before the verb, not at the end like English 'too'."},{"hanzi":"还","pinyin":"hái","tones":"2","en":"still, also","pos":"adverb","radical":"辶","strokes":7,"ex_zh":"我还有一个。","ex_en":"I have one more.","tier":3,"family":"time","trap":"Second tone; 还 is 'still/also', 或者 is 'or'."},{"hanzi":"就","pinyin":"jiù","tones":"4","en":"then; right away","pos":"adverb","radical":"尢","strokes":12,"ex_zh":"我就来。","ex_en":"I am coming right away.","tier":3,"family":"time","trap":"Fourth tone; 就 marks that something follows at once, it is not 'only'."},{"hanzi":"很","pinyin":"hěn","tones":"3","en":"very","pos":"adverb","radical":"彳","strokes":9,"ex_zh":"他很高。","ex_en":"He is very tall.","tier":3,"family":"adjectives","trap":"Third tone; before another third tone it is said second, as in 很好."},{"hanzi":"太","pinyin":"tài","tones":"4","en":"too, excessively","pos":"adverb","radical":"大","strokes":4,"ex_zh":"太贵了！","ex_en":"Too expensive!","tier":3,"family":"adjectives","trap":"Fourth tone; 太 needs 了 at the end for 'too ...'."},{"hanzi":"真","pinyin":"zhēn","tones":"1","en":"really, truly","pos":"adverb","radical":"目","strokes":10,"ex_zh":"真好吃！","ex_en":"Really tasty!","tier":3,"family":"adjectives","trap":"First tone; 真 is an exclamation, 很 is the neutral 'very'."},{"hanzi":"最","pinyin":"zuì","tones":"4","en":"most","pos":"adverb","radical":"冂","strokes":12,"ex_zh":"他最高。","ex_en":"He is the tallest.","tier":3,"family":"adjectives","trap":"Fourth tone; 最 replaces 很, do not use both."},{"hanzi":"更","pinyin":"gèng","tones":"4","en":"even more","pos":"adverb","radical":"曰","strokes":7,"ex_zh":"这个更好。","ex_en":"This one is even better.","tier":3,"family":"adjectives","trap":"Fourth tone; 更 compares two, 最 picks one out of many."},{"hanzi":"比较","pinyin":"bǐjiào","tones":"3 4","en":"rather, comparatively","pos":"adverb","radical":"比","strokes":4,"ex_zh":"这个比较好。","ex_en":"This one is rather good.","tier":3,"family":"adjectives","trap":"较 falls; 比较 is softer than 很, a mild 'quite'."},{"hanzi":"以前","pinyin":"yǐqián","tones":"3 2","en":"before, in the past","pos":"noun","radical":"人","strokes":4,"ex_zh":"我以前住这里。","ex_en":"I used to live here.","tier":3,"family":"time","trap":"前 rises; 以前 is time, 前面 is position."},{"hanzi":"以后","pinyin":"yǐhòu","tones":"3 4","en":"after, later","pos":"noun","radical":"人","strokes":4,"ex_zh":"以后再说。","ex_en":"We will talk later.","tier":3,"family":"time","trap":"后 falls; 以后 can follow a verb to mean 'after doing'."},{"hanzi":"厨房","pinyin":"chúfáng","tones":"2 2","en":"kitchen","pos":"noun","radical":"厂","strokes":12,"ex_zh":"妈妈在厨房。","ex_en":"Mom is in the kitchen.","tier":3,"family":"nature","trap":"Both second tone; 房 here means 'room', not 'house'."},{"hanzi":"洗手间","pinyin":"xǐshǒujiān","tones":"3 3 1","en":"bathroom","pos":"noun","radical":"氵","strokes":9,"ex_zh":"洗手间在哪？","ex_en":"Where is the bathroom?","tier":3,"family":"nature","trap":"Three syllables; the first two third tones make the first sound second."},{"hanzi":"花园","pinyin":"huāyuán","tones":"1 2","en":"garden","pos":"noun","radical":"艹","strokes":7,"ex_zh":"花园很漂亮。","ex_en":"The garden is pretty.","tier":3,"family":"nature","trap":"园 rises; 花园 is a garden, 公园 a public park."},{"hanzi":"图书馆","pinyin":"túshūguǎn","tones":"2 1 3","en":"library","pos":"noun","radical":"囗","strokes":8,"ex_zh":"我去图书馆。","ex_en":"I go to the library.","tier":3,"family":"school","trap":"Three syllables: tú shū guǎn; 馆 is third tone."},{"hanzi":"医院","pinyin":"yīyuàn","tones":"1 4","en":"hospital","pos":"noun","radical":"匸","strokes":7,"ex_zh":"他在医院。","ex_en":"He is in hospital.","tier":3,"family":"nature","trap":"院 falls; 医生 is the doctor, 医院 the building."},{"hanzi":"银行","pinyin":"yínháng","tones":"2 2","en":"bank","pos":"noun","radical":"钅","strokes":11,"ex_zh":"银行在那边。","ex_en":"The bank is over there.","tier":3,"family":"nature","trap":"行 is háng here, not xíng; both syllables rise."},{"hanzi":"超市","pinyin":"chāoshì","tones":"1 4","en":"supermarket","pos":"noun","radical":"走","strokes":12,"ex_zh":"我去超市。","ex_en":"I go to the supermarket.","tier":3,"family":"nature","trap":"市 falls; 超市 is the shop, 城市 is a city."},{"hanzi":"钱","pinyin":"qián","tones":"2","en":"money","pos":"noun","radical":"钅","strokes":10,"ex_zh":"我没有钱。","ex_en":"I have no money.","tier":3,"family":"food","trap":"Second tone; q is aspirated, unlike j."},{"hanzi":"块","pinyin":"kuài","tones":"4","en":"yuan; a piece","pos":"measure","radical":"土","strokes":7,"ex_zh":"这个五块钱。","ex_en":"This costs five yuan.","tier":3,"family":"measure","trap":"Spoken yuan; do not confuse with 快 kuài, fast, which has the same sound."},{"hanzi":"元","pinyin":"yuán","tones":"2","en":"yuan (currency)","pos":"measure","radical":"儿","strokes":4,"ex_zh":"一共十元。","ex_en":"Ten yuan in total.","tier":3,"family":"measure","trap":"Second tone; 元 is the written form, 块 the spoken one."},{"hanzi":"贵","pinyin":"guì","tones":"4","en":"expensive","pos":"adjective","radical":"贝","strokes":9,"ex_zh":"太贵了！","ex_en":"Too expensive!","tier":3,"family":"adjectives","trap":"Fourth tone; g is unaspirated, unlike k."},{"hanzi":"重要","pinyin":"zhòngyào","tones":"4 4","en":"important","pos":"adjective","radical":"里","strokes":9,"ex_zh":"这个很重要。","ex_en":"This is very important.","tier":3,"family":"adjectives","trap":"Both fall; 重 is chóng 'heavy again' in other words."},{"hanzi":"容易","pinyin":"róngyì","tones":"2 4","en":"easy","pos":"adjective","radical":"宀","strokes":10,"ex_zh":"这个很容易。","ex_en":"This is very easy.","tier":3,"family":"adjectives","trap":"易 falls; 容 is second tone, not neutral."},{"hanzi":"困难","pinyin":"kùnnan","tones":"4 5","en":"difficult; difficulty","pos":"adjective","radical":"囗","strokes":7,"ex_zh":"这个问题困难。","ex_en":"This problem is difficult.","tier":3,"family":"adjectives","trap":"Second syllable neutral: kùnnan, not kùnnán."},{"hanzi":"安静","pinyin":"ānjìng","tones":"1 4","en":"quiet","pos":"adjective","radical":"宀","strokes":6,"ex_zh":"请安静。","ex_en":"Please be quiet.","tier":3,"family":"adjectives","trap":"静 falls; 安 is first tone, high and flat."},{"hanzi":"聪明","pinyin":"cōngming","tones":"1 5","en":"clever","pos":"adjective","radical":"耳","strokes":15,"ex_zh":"他很聪明。","ex_en":"He is very clever.","tier":3,"family":"adjectives","trap":"Second syllable neutral: cōngming, not cōngmíng."},{"hanzi":"努力","pinyin":"nǔlì","tones":"3 4","en":"hard-working; to work hard","pos":"adjective","radical":"力","strokes":7,"ex_zh":"她很努力。","ex_en":"She works very hard.","tier":3,"family":"adjectives","trap":"力 falls; 努 is third tone, so pitch dips first."},{"hanzi":"健康","pinyin":"jiànkāng","tones":"4 1","en":"healthy","pos":"adjective","radical":"亻","strokes":10,"ex_zh":"他很健康。","ex_en":"He is healthy.","tier":3,"family":"body","trap":"康 is first tone; 健 falls, it is not flat."},{"hanzi":"舒服","pinyin":"shūfu","tones":"1 5","en":"comfortable","pos":"adjective","radical":"舌","strokes":12,"ex_zh":"床很舒服。","ex_en":"The bed is comfortable.","tier":3,"family":"adjectives","trap":"Second syllable neutral: shūfu, not shūfú."},{"hanzi":"有趣","pinyin":"yǒuqù","tones":"3 4","en":"interesting","pos":"adjective","radical":"月","strokes":6,"ex_zh":"这本书有趣。","ex_en":"This book is interesting.","tier":3,"family":"adjectives","trap":"趣 falls; 有 is third tone and dips first."},{"hanzi":"安全","pinyin":"ānquán","tones":"1 2","en":"safe","pos":"adjective","radical":"宀","strokes":6,"ex_zh":"这里很安全。","ex_en":"It is safe here.","tier":3,"family":"adjectives","trap":"全 rises; q is aspirated, unlike j."},{"hanzi":"颜色","pinyin":"yánsè","tones":"2 4","en":"colour","pos":"noun","radical":"页","strokes":15,"ex_zh":"你喜欢什么颜色？","ex_en":"What colour do you like?","tier":3,"family":"adjectives","trap":"色 falls; 颜 is second tone, not first."},{"hanzi":"声音","pinyin":"shēngyīn","tones":"1 1","en":"sound, voice","pos":"noun","radical":"士","strokes":7,"ex_zh":"声音很大。","ex_en":"The sound is loud.","tier":3,"family":"nature","trap":"Both first tone; 声 is not neutral here."},{"hanzi":"故事","pinyin":"gùshi","tones":"4 5","en":"story","pos":"noun","radical":"攵","strokes":9,"ex_zh":"讲个故事吧。","ex_en":"Tell a story.","tier":3,"family":"school","trap":"Second syllable neutral: gùshi, not gùshì."},{"hanzi":"生日","pinyin":"shēngrì","tones":"1 4","en":"birthday","pos":"noun","radical":"生","strokes":5,"ex_zh":"今天是我生日。","ex_en":"Today is my birthday.","tier":3,"family":"time","trap":"日 falls; 生 is first tone, high and flat."},{"hanzi":"礼物","pinyin":"lǐwù","tones":"3 4","en":"gift","pos":"noun","radical":"礻","strokes":5,"ex_zh":"这是给你的礼物。","ex_en":"This is a gift for you.","tier":3,"family":"food","trap":"物 falls; 礼 is third tone, so pitch dips first."},{"hanzi":"假期","pinyin":"jiàqī","tones":"4 1","en":"holiday, vacation","pos":"noun","radical":"亻","strokes":11,"ex_zh":"假期很快乐。","ex_en":"The holiday is happy.","tier":3,"family":"time","trap":"期 is first tone; 假 is jiǎ 'fake' in other words."}];
